const labels={title:'Title',description:'Description',statusId:'Status',priority:'Priority',assigneeId:'Assignee',estimate:'Estimate',dueDate:'Due date',parentId:'Parent issue',labelIds:'Labels',body:'Comment',name:'Label name',color:'Color'};
export function DraftDecision(props) {
  const key=JSON.stringify([props.before,props.mine,props.current,props.latest?.revision]);
  return <DraftComparison key={key} {...props}/>;
}
function DraftComparison({error,latest,before,mine,current,onInspect,onLoad,onApply,busy,display}) {
  const [choices,setChoices]=useState({});
  if(!error)return null;
  const lost=[401,403,404].includes(error.status),comparison=latest?compareDraft(before,mine,current):null;
  const unresolved=comparison?.conflicts.some(field=>!choices[field.key]);
  function value(field,item) {
    if(field==='description'||field==='body')return <><pre>{item===''?'(empty)':item}</pre><Markdown source={item??''}/></>;
    return <span>{display?.(field,item)??(item==null||item===''?'Not set':Array.isArray(item)?item.length?item.join(', '):'No labels':String(item))}</span>;
  }
