    {onInspect&&<Button type="button" disabled={busy} onClick={onInspect}>Inspect latest version</Button>}
    {latest&&<>
      <details><summary>Latest saved snapshot</summary><pre aria-label="Latest saved version">{JSON.stringify(latest,null,2)}</pre></details>
      <p>Independent newer fields are preserved. Each overlapping edit requires your own choice. Applying choices updates this draft; Save remains a separate action and checks the latest revision again.</p>
      {comparison.fields.filter(field=>field.localChanged||field.peerChanged).map(field=><fieldset key={field.key} aria-label={labels[field.key]??field.key} disabled={busy||lost}>
        <legend>{labels[field.key]??field.key}{field.conflict?' — overlapping edits':field.localChanged?' — your edit':' — newer saved edit'}</legend>
        <dl><dt>Before</dt><dd>{value(field.key,field.before)}</dd><dt>Mine</dt><dd>{value(field.key,field.mine)}</dd><dt>Latest</dt><dd>{value(field.key,field.latest)}</dd></dl>
        {field.conflict&&<><label><input type="radio" name={'resolve-'+field.key} value="mine" checked={choices[field.key]==='mine'} onChange={()=>setChoices(previous=>({...previous,[field.key]:'mine'}))}/>Use mine for {labels[field.key]??field.key}</label><label><input type="radio" name={'resolve-'+field.key} value="latest" checked={choices[field.key]==='latest'} onChange={()=>setChoices(previous=>({...previous,[field.key]:'latest'}))}/>Use latest for {labels[field.key]??field.key}</label></>}
      </fieldset>)}
      <Button type="button" disabled={busy||lost||unresolved} onClick={()=>onApply(latest,resolveDraft(comparison,choices))}>{comparison.conflicts.length?'Apply selected field choices':'Keep my changes on latest version'}</Button>
      <Button type="button" disabled={busy||lost} onClick={()=>{if(globalThis.confirm('Replace your local draft with the latest saved version?'))onLoad(latest);}}>Load latest version</Button>
    </>}
  </aside>;
}

import {DraftDecision} from './issue-draft.jsx';
import {issueDraftValues,discardDraft} from './issue-draft.js';
