    if(field==='assigneeId')return records.find(record=>record.assignee?.id===value)?.assignee?.name;
    if(field==='labelIds'&&Array.isArray(value)){const names=new Map(records.flatMap(record=>(record.labels??[]).map(label=>[label.id,label.name])));return value.length?value.map(id=>names.get(id)??id).join(', '):'No labels';}
  }
