      <p className="field-help">Raw HTML is displayed as text. Clearing an optional field removes its saved value.</p>
      <div className="form-grid">
        <Field label="Status" error={errors.statusId}><select name="statusId" value={form.statusId} onChange={input('statusId')}><option value="">First workflow status</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
        <Field label="Priority" error={errors.priority}><select name="priority" value={form.priority} onChange={input('priority')}>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
        <div><WorkPicker api={api} project={project} type="users" permission="issue:write" label="Assignee" value={form.assigneeId} onChange={id=>change('assigneeId',id)} placeholder="Unassigned"/><Notice error={errors.assigneeId}/></div>
        <Field label="Estimate" name="estimate" type="number" min="0" max="1000000" step="any" value={form.estimate} onInput={input('estimate')} error={errors.estimate}/>
        <Field label="Due date" name="dueDate" type="date" value={form.dueDate} onInput={input('dueDate')} error={errors.dueDate}/>
        <div><WorkPicker api={api} project={project} type="parents" issueId={issue?.id} permission="issue:write" label="Parent issue" value={form.parentId} onChange={id=>change('parentId',id)} placeholder="No parent"/><Notice error={errors.parentId}/></div>
      </div>
      <LabelSelection api={api} project={project} initial={issue?.labels} value={form.labelIds} onChange={value=>change('labelIds',value)}/><Notice error={errors.labelIds}/>
